function EXTRA(R,ICON){
 /* hook: rain floods a fixed threshold; the tracker stays locked */
 ICON.rdRain=(x,y)=>{let s=0x5eed;const rnd=()=>{s=(s*1103515245+12345)&0x7fffffff;return s/0x7fffffff};
  let p=[];for(let i=0;i<=80;i++){const xx=150+210*i/80,rain=(i>30&&i<62)?1.8:1;p.push(`${xx.toFixed(1)},${(130-(rnd()*34+6)*rain).toFixed(1)}`)}
  return `<g transform="translate(${x-190} ${y-85})">${RD_box(0,0,380,170,{fill:'#FFFFFF',st:INK,sw:3,r:18})}
  <ellipse cx="74" cy="56" rx="50" ry="24" fill="#CED4DA"/><ellipse cx="50" cy="66" rx="30" ry="18" fill="#CED4DA"/><ellipse cx="100" cy="68" rx="30" ry="18" fill="#CED4DA"/>
  ${[40,64,88,112].map((xx,i)=>RD_L(xx,96+(i%2)*8,xx-8,116+(i%2)*8,BLU,4)).join('')}
  ${RD_L(150,130,360,130,RD_G,2)}<polyline points="${p.join(' ')}" fill="none" stroke="${BLU}" stroke-width="2.5"/>
  ${RD_L(150,78,360,78,RED,3,'stroke-dasharray="8 6"')}${RD_T(360,32,'fixed threshold',{fs:22,fw:800,a:'end',fill:RED})}
  ${RD_T(255,160,'false alarms',{fs:22,fw:800,a:'middle',fill:RED})}</g>`};
 ICON.rdTrack=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${RD_box(0,0,380,170,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}
  ${RD_dish(30,100,90,INK)}${RD_lobe(96,100,230,22,-12,BLU,.22)}
  <g transform="translate(322 48) rotate(-12)"><polygon points="32,0 24,-4 6,-4 -6,-28 -14,-28 -6,-4 -22,-4 -30,-14 -36,-14 -32,0 -36,14 -30,14 -22,4 -6,4 -14,28 -6,28 6,4 24,4" fill="${INK}"/></g>
  ${RD_T(250,154,'locked on one target',{fs:22,fw:800,a:'middle',fill:BLU})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.rcTrack=(x,y)=>`<g transform="translate(${x-210} ${y-165})">
  ${RD_L(20,180,400,180,RD_G,3)}${RD_L(210,30,210,320,RD_G,3)}
  ${RD_L(30,300,390,60,BLU,6)}
  ${RD_L(270,180,270,140,ORG,3,'stroke-dasharray="6 5"')}${RD_L(210,140,270,140,ORG,3,'stroke-dasharray="6 5"')}<circle cx="270" cy="140" r="11" fill="${ORG}"/>
  ${RD_T(30,50,'Δ/Σ',{fs:28,fw:800,fill:INK})}${RD_T(400,218,'θ',{fs:28,fw:800,a:'end',fill:INK})}
  ${RD_T(252,122,'0.12',{fs:26,fw:800,a:'end',fill:ORG})}${RD_T(270,214,'0.0667°',{fs:24,fw:800,a:'middle',fill:ORG})}
  ${RD_T(110,290,'slope k',{fs:26,fw:800,fill:BLU})}</g>`;
 ICON.rcDetect=(x,y)=>`<g transform="translate(${x-210} ${y-165})">
  ${[0,1,2,3,4,5,6,7,8].map(i=>`<rect x="${12+i*44}" y="40" width="40" height="64" rx="6" fill="${i===4?'#FFF4E6':'#FFFFFF'}" stroke="${i===4?ORG:(i===3||i===5)?RD_LG:BLU}" stroke-width="3"${(i===3||i===5)?' stroke-dasharray="6 4"':''}/>`).join('')}
  ${RD_T(208,82,'CUT',{fs:22,fw:800,a:'middle',fill:ORG})}
  ${RD_ar(78,112,170,186,BLU,4)}${RD_ar(342,112,250,186,BLU,4)}
  ${RD_box(100,190,220,56,{fill:'#DBE4FF',st:BLU,sw:3,r:10})}${RD_T(210,226,'Z × α',{fs:28,fw:800,a:'middle',fill:BLU})}
  ${RD_T(210,300,'α = 12.45, N = 16',{fs:28,fw:800,a:'middle',fill:INK})}</g>`;
 ICON.rcHW=(x,y)=>{const Y=d=>84-d*1.2;return `<g transform="translate(${x-210} ${y-165})">
  ${RD_L(60,20,60,310,RD_G,3)}
  <rect x="64" y="${Y(80)+44}" width="336" height="${Y(10)-Y(80)-8}" fill="${ORG}" fill-opacity=".14"/><rect x="64" y="${Y(10)+44}" width="336" height="${Y(-100)-Y(10)-8}" fill="${GRN}" fill-opacity=".10"/>
  ${[[80,'+80 dBm pulse',BLU],[10,'+10 dBm leak',ORG],[-100,'−100 dBm echo',GRN]].map(([d,t,col])=>RD_L(60,Y(d)+40,400,Y(d)+40,col,7)+RD_T(400,Y(d)+30,t,{fs:26,fw:800,a:'end',fill:col})).join('')}
  ${RD_ar(110,Y(80)+48,110,Y(10)+32,ORG,4)}${RD_T(124,(Y(80)+Y(10))/2+50,'70 dB',{fs:26,fw:800,fill:ORG})}
  ${RD_ar(110,Y(10)+48,110,Y(-100)+32,GRN,4)}${RD_T(124,(Y(10)+Y(-100))/2+50,'110 dB',{fs:26,fw:800,fill:GRN})}</g>`};
}
